    RunicServeOnlyApplication.CreateStartInfo("path/to/MyApp.dll"));
await page.GotoAsync(app.Url.ToString());
// ...
Assert.Equal(0, await app.StopAsync());

using var platform = RunicServeOnlyTestPlatform.Create();
var start = platform.Configure(RunicServeOnlyApplication.CreateStartInfo(appPath));
await using var app = await RunicServeOnlyApplication.StartAsync(start);
platform.EnqueueOpenFile("notes.txt", "Hello");
await page.GetByRole(AriaRole.Button, new() { Name = "Open" }).ClickAsync();
var shown = await platform.WaitForEventAsync(e => e.Operation == "openFile");

var start = RunicServeOnlyApplication.CreateStartInfo("path/to/Tool.dll");
start.ArgumentList.Add("hosted");                    // The parameter the guest defines for hosted mode.
await using var host = await RunicTestHost.StartGuestAsync(start);
var window = await host.WaitForWindowAsync("MainWindow", TimeSpan.FromSeconds(30));
await page.GotoAsync(window.LaunchUrl.ToString());    // Playwright loads the guest's page as the host's window would.
Assert.True(await window.RequestCloseAsync());
Assert.Equal(0, await host.StopAsync());

var page = await editor.MountPresentationAsync();
page.Handle<DiscardRequest, bool>(vm => vm.ConfirmDiscard, request => true);
(await editor.ExecuteAsync(vm => vm.DiscardCommand)).ThrowIfFailed();
var focus = Assert.Single(page.TakeViewRequests(vm => vm.Focus));

